  "a_sentences": [
    {
      "a_text": "Die Vorinstanz bestätigte den Einspracheentscheid der Suva und verneinte eine über den 11. November 2024 hinausgehende Leistungspflicht für den Unfall vom 23. Mai 2024 (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Die Vorinstanz verneinte zudem in Würdigung der Akten einen natürlichen Kausalzusammenhang zwischen dem Ereignis und den körperlich erklärbaren Beschwerden (P2).",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Eine Beschwerde an das Bundesgericht muss die Begehren und deren Begründung enthalten und im Einzelnen darlegen, welche Vorschriften und weshalb sie verletzt worden sind (P3).",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Dabei ist konkret auf die für das Ergebnis massgeblichen Erwägungen der Vorinstanz einzugehen und im Einzelnen aufzuzeigen, welche Vorschriften verletzt wurden (P4).",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Die Unfallschwere beurteilt sich nach objektivierter Betrachtungsweise allein auf Grund des augenfälligen Geschehensablaufs mit den sich dabei entwickelnden Kräften (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Allein die Forderung nach Berücksichtigung des Verletzungspotenzials genügt nicht (P6).",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Die Vorinstanz verneinte eine Leistungspflicht für psychische und organisch nicht objektivierbare Beschwerden mangels adäquater Kausalität zum als mittelschwer, im Grenzbereich zu den leichten Ereignissen einreihbaren Unfall (P7).",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Das Bundesgericht erkennt keine hinreichende Rüge, da der Versicherte nicht darlegt, inwiefern die vorinstanzlichen Sachverhaltsfeststellungen unrichtig sind oder Bundesrecht verletzt wurde (P8).",
      "b_propositions": ["P8"]
    }
  ]
}
